<script setup>import{useForm}from'@inertiajs/vue3';import AdminLayout from '../../Layouts/AdminLayout.vue';const form=useForm({current_password:'',password:'',password_confirmation:''});function save(){form.post('/admin/password')}</script>
<template><AdminLayout title="修改密码" section="账号 / 修改密码" description="设置管理员登录密码。"><section class="card" style="max-width:680px"><div class="card-body"><form class="form-stack" @submit.prevent="save"><div class="form-field"><label>当前密码</label><el-input v-model="form.current_password" type="password" show-password required /></div><div class="form-field"><label>新密码（至少 16 位）</label><el-input v-model="form.password" type="password" show-password minlength="16" required /></div><div class="form-field"><label>确认新密码</label><el-input v-model="form.password_confirmation" type="password" show-password minlength="16" required /></div><div class="section-actions"><el-button type="primary" native-type="submit" :loading="form.processing">更新密码</el-button></div></form></div></section></AdminLayout></template>
